      "@type": "FAQPage",
      "mainEntity": [
        {
          "@type": "Question",
          "name": "What is a Section 143(3) order?",
          "acceptedAnswer": {
            "@type": "Answer",
            "text": "Final assessment order after detailed scrutiny of ITR. Contains AO's assessment of total income with additions/disallowances, final tax liability, and penalty initiation. Accompanied by S.156 demand if tax payable."
          }
        },
        {
          "@type": "Question",
          "name": "How are scrutiny cases selected?",
          "acceptedAnswer": {
            "@type": "Answer",
            "text": "CASS system flags returns: AIS mismatch, high refunds, large cash transactions, disproportionate deductions, unreported capital gains, foreign assets. Can be limited (specific issue) or complete (all aspects)."
          }
        },
        {
          "@type": "Question",
          "name": "What are additions and disallowances?",
          "acceptedAnswer": {
            "@type": "Answer",
            "text": "Additions: amounts AO adds to declared income (unreported capital gains). Disallowances: deductions AO rejects (HRA without receipts, 80C without proof). Both increase taxable income and tax demand."
          }
        },
        {
          "@type": "Question",
          "name": "How to appeal against 143(3)?",
          "acceptedAnswer": {
            "@type": "Answer",
            "text": "File Form 35 to CIT(A)/NFAC within 30 days. Pay appeal fee. Submit grounds of appeal for each addition. Apply for stay on 20% payment. Patron handles complete appeal process."
          }
        },
        {
          "@type": "Question",
          "name": "What is Section 270A penalty?",
          "acceptedAnswer": {
            "@type": "Answer",
            "text": "50% of tax on underreported income (bona fide error). 200% for misreporting (false entries, bogus expenses). From AY 2027-28, penalty imposed within assessment order itself."
          }
        },
        {
          "@type": "Question",
          "name": "Can I request stay of demand?",
          "acceptedAnswer": {
            "@type": "Answer",
            "text": "Yes. Apply for stay during pending appeal. Typically granted on 20% of disputed amount. Prevents bank attachment, refund adjustment, salary deduction. Patron files with legal grounds."
          }
        },
        {
          "@type": "Question",
          "name": "What is the show cause stage?",
          "acceptedAnswer": {
            "@type": "Answer",
            "text": "AO issues Draft Assessment Order proposing additions. You get 3-7 days to respond. This response often determines the final order. Most critical stage - professional response essential."
          }
